<?php require_once 'db.php'; $page_title='Sign in'; csrf_check(); $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';$s=db()->prepare("SELECT * FROM users WHERE email=?");$s->execute([$email]);$u=$s->fetch();if($u&&password_verify($pass,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['user_name']=$u['name'];$_SESSION['role']=$u['role'];flash('Welcome back, '.$u['name'].'!');go('index.php');}else{$err='Email or password is incorrect.';}} include 'header.php'; ?>
<section class="section" style="max-width:600px;margin:auto"><div class="eyebrow">WELCOME BACK</div><h1 style="font-size:3rem">Sign in.</h1><?php if($err): ?><div class="notice"><?= h($err) ?></div><?php endif; ?><form class="panel" method="post"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Password</label><input name="password" type="password" required></div><button class="btn">Sign in</button><p class="muted"><a href="forgot_password.php">Forgot password?</a> · <a href="register.php">Create an account</a></p></form></section><?php include 'footer.php'; ?>